import { Component, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { RouterModule } from '@angular/router';
import { FormsModule } from '@angular/forms';
import { ApiService } from '../../../core/services/api.service';
import { AuthService } from '../../../core/services/auth.service';

@Component({
  selector: 'app-profile',
  standalone: true,
  imports: [CommonModule, RouterModule, FormsModule],
  template: `
    <div class="page-header"><div class="container"><h1>Hồ Sơ Cá Nhân</h1></div></div>
    <section class="section">
      <div class="container container-sm">
        <div class="profile-card card">
          <div class="card-body">
            <form (ngSubmit)="save()">
              <div class="form-group"><label>Họ tên</label><input type="text" class="form-control" [(ngModel)]="form.fullName" name="fullName"></div>
              <div class="form-group"><label>Email</label><input type="email" class="form-control" [(ngModel)]="form.email" name="email" disabled></div>
              <div class="form-group"><label>Số điện thoại</label><input type="tel" class="form-control" [(ngModel)]="form.phone" name="phone"></div>
              <div class="form-success" *ngIf="success">{{ success }}</div>
              <button type="submit" class="btn btn-primary" [disabled]="loading">Lưu thay đổi</button>
            </form>
            <hr style="margin:2rem 0;">
            <h3>Đổi mật khẩu</h3>
            <div class="form-group"><label>Mật khẩu hiện tại</label><input type="password" class="form-control" [(ngModel)]="passwordForm.current" name="current"></div>
            <div class="form-group"><label>Mật khẩu mới</label><input type="password" class="form-control" [(ngModel)]="passwordForm.newPass" name="newPass"></div>
            <div class="form-error" *ngIf="pwError">{{ pwError }}</div>
            <div class="form-success" *ngIf="pwSuccess">{{ pwSuccess }}</div>
            <button class="btn btn-outline" (click)="changePassword()" [disabled]="loading">Đổi mật khẩu</button>
          </div>
        </div>
      </div>
    </section>
  `,
  styles: [`.profile-card { max-width: 560px; } .form-success { color: var(--secondary); font-weight: 600; padding: 0.75rem; background: rgba(25,135,84,0.1); border-radius: 8px; margin-bottom: 1rem; }`]
})
export class ProfileComponent implements OnInit {
  form: any = {};
  success = '';
  passwordForm: any = {};
  pwError = '';
  pwSuccess = '';
  loading = false;

  constructor(private api: ApiService, public auth: AuthService) {}

  ngOnInit() {
    this.form = { ...this.auth.user() };
  }

  save() {
    this.loading = true;
    this.api.updateProfile(this.form).subscribe({
      next: (res) => {
        this.auth.updateUser(res.user);
        this.success = 'Cập nhật thành công!';
        this.loading = false;
        setTimeout(() => this.success = '', 3000);
      },
      error: () => { this.loading = false; }
    });
  }

  changePassword() {
    if (!this.passwordForm.current || !this.passwordForm.newPass) return;
    this.loading = true;
    this.pwError = '';
    this.api.changePassword(this.passwordForm).subscribe({
      next: () => {
        this.pwSuccess = 'Đổi mật khẩu thành công!';
        this.passwordForm = {};
        this.loading = false;
        setTimeout(() => this.pwSuccess = '', 3000);
      },
      error: (err) => {
        this.pwError = err.error?.error || 'Đổi mật khẩu thất bại';
        this.loading = false;
      }
    });
  }
}
